package fileservice

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"os"
	"path"
	"path/filepath"
	"strings"
	"time"

	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"

	pb "github.com/example/fileservice/proto"
)

const baseDir = "/var/data/files"

type AuditEntry struct {
	Timestamp time.Time
	User      string
	Action    string
	Resource  string
	Checksum  string
	Allowed   bool
}

type FileServer struct {
	pb.UnimplementedFileServiceServer
	auditLog []AuditEntry
}

func NewFileServer() *FileServer {
	return &FileServer{
		auditLog: make([]AuditEntry, 0, 1024),
	}
}

// sanitizePath removes path traversal sequences and validates the path
func sanitizePath(userPath string) (string, error) {
	// Reject obviously malicious patterns
	if strings.Contains(userPath, "..") {
		return "", fmt.Errorf("path traversal detected")
	}
	if strings.HasPrefix(userPath, "/") {
		return "", fmt.Errorf("absolute paths not allowed")
	}
	// Clean the path to normalize it
	cleaned := path.Clean(userPath)
	return cleaned, nil
}

// resolveAndValidate builds the full path and ensures it's within baseDir
func resolveAndValidate(sanitized string) (string, error) {
	// Build the full filesystem path
	fullPath := filepath.Join(baseDir, sanitized)

	// Resolve any symlinks to get the real path
	resolved, err := filepath.EvalSymlinks(filepath.Dir(fullPath))
	if err != nil {
		// If parent dir doesn't exist, construct the expected path
		resolved = filepath.Dir(fullPath)
	}
	finalPath := filepath.Join(resolved, filepath.Base(fullPath))

	// Verify the resolved path is still under baseDir
	if !strings.HasPrefix(finalPath, baseDir) {
		return "", fmt.Errorf("path escapes base directory")
	}
	return finalPath, nil
}

// computeChecksum generates SHA-256 hash for audit trail integrity
func computeChecksum(filePath string, user string) string {
	h := sha256.New()
	h.Write([]byte(filePath))
	h.Write([]byte(user))
	h.Write([]byte(time.Now().UTC().Format(time.RFC3339)))
	return hex.EncodeToString(h.Sum(nil))
}

func (s *FileServer) logAudit(user, action, resource string, allowed bool) string {
	checksum := computeChecksum(resource, user)
	entry := AuditEntry{
		Timestamp: time.Now().UTC(),
		User:      user,
		Action:    action,
		Resource:  resource,
		Checksum:  checksum,
		Allowed:   allowed,
	}
	s.auditLog = append(s.auditLog, entry)
	return checksum
}

func (s *FileServer) ReadFile(ctx context.Context, req *pb.ReadFileRequest) (*pb.ReadFileResponse, error) {
	user := req.GetUsername()
	if user == "" {
		return nil, status.Error(codes.Unauthenticated, "username required")
	}

	requestPath := req.GetFilePath()

	// Stage 1: Sanitize the user-provided path
	sanitized, err := sanitizePath(requestPath)
	if err != nil {
		s.logAudit(user, "READ", requestPath, false)
		return nil, status.Errorf(codes.InvalidArgument, "invalid path: %v", err)
	}

	// Stage 2: Resolve to absolute path and validate containment
	finalPath, err := resolveAndValidate(sanitized)
	if err != nil {
		s.logAudit(user, "READ", sanitized, false)
		return nil, status.Errorf(codes.PermissionDenied, "access denied: %v", err)
	}

	// Stage 3: Read the file
	file, err := os.Open(finalPath)
	if err != nil {
		s.logAudit(user, "READ", finalPath, false)
		return nil, status.Errorf(codes.NotFound, "file not found")
	}
	defer file.Close()

	data, err := io.ReadAll(file)
	if err != nil {
		s.logAudit(user, "READ", finalPath, false)
		return nil, status.Errorf(codes.Internal, "read error")
	}

	auditID := s.logAudit(user, "READ", finalPath, true)

	return &pb.ReadFileResponse{
		Content:  data,
		AuditId:  auditID,
		FileSize: int64(len(data)),
	}, nil
}

func (s *FileServer) GetAuditLog(ctx context.Context, req *pb.AuditLogRequest) (*pb.AuditLogResponse, error) {
	var entries []*pb.AuditEntry
	for _, e := range s.auditLog {
		entries = append(entries, &pb.AuditEntry{
			Timestamp: e.Timestamp.Unix(),
			User:      e.User,
			Action:    e.Action,
			Resource:  e.Resource,
			Allowed:   e.Allowed,
		})
	}
	return &pb.AuditLogResponse{Entries: entries}, nil
}
